actions.script:
if (!(ec.entity.find('mantle.request.support.CaseProfile').condition('requestId', requestId).disableAuthz().count() > 0)) return
ec.message.pushErrors()
try {
    const sla = ec.resource.script('component://mr-mantle/service/mantle/request/Sla.js')
    const op = {status: 'recordStatus', message: 'recordMessage', work: 'recordWork'}[kind]
    if (!op) throw new Error('Unknown case event kind ' + kind)
    sla.execute(op, context)
} catch (err) {
    ec.logger.error(`Case ${requestId}: the service level event (${kind}) was not recorded: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
